/// <summary>
/// Get the related pricing attribute.
/// </summary>
/// <returns>The pricing attribute.</returns>
public GUPIPricingAttribute pricingAttribute()
{
    return GUPPricingAttributeRepository::priceAttribute(
        this.PriceAttributeClassId,
        this.AttributeProviderClassId,
        this.AttributeName,
        this.TypeName);
}

    public static GUPPricingAttributeLink find(RecId _recId, boolean _update = false)
    {
        GUPPricingAttributeLink  pricingAttributeLink;

        pricingAttributeLink.selectForUpdate(_update);

        if (_recId)
        {
            select firstonly pricingAttributeLink
                where pricingAttributeLink.RecId == _recId;
        }

        return pricingAttributeLink;
    }

    public Set getAttributeGroupRecIdRecordSet()
    {
        GUPPricingAttributeLink pricingAttributeLink;
        GUPPricingAttributeGroup pricingAttributeGroup;
        Set recordSet = new Set(Types::Int64);

        while select PriceAttributeGroup from pricingAttributeLink join pricingAttributeGroup
            where pricingAttributeLink.PriceAttributeGroup == pricingAttributeGroup.RecId
                && pricingAttributeGroup.IsValid == NoYes::Yes
                && pricingAttributeLink.PriceAttributeClassId == this.PriceAttributeClassId
                && pricingAttributeLink.AttributeName == this.AttributeName
                && pricingAttributeLink.TypeName == this.TypeName
                && pricingAttributeLink.DefaultValue == this.DefaultValue
        {
            recordSet.add(pricingAttributeLink.PriceAttributeGroup);
        }

        return recordSet;
    }

    public void moveUp()
    {
        GUPPricingAttributeLink swapPricingAttributeLink;

        select forupdate firstonly Priority from swapPricingAttributeLink
            order by Priority desc
            where this.PriceAttributeGroup == swapPricingAttributeLink.PriceAttributeGroup &&
            this.Priority > swapPricingAttributeLink.Priority;

        if (swapPricingAttributeLink)
        {
            this.swapPriority(swapPricingAttributeLink);
        }
    }

    public void moveDown()
    {
        GUPPricingAttributeLink swapPricingAttributeLink;

        select forupdate firstonly Priority from swapPricingAttributeLink
            order by Priority asc
            where this.PriceAttributeGroup == swapPricingAttributeLink.PriceAttributeGroup &&
            this.Priority < swapPricingAttributeLink.Priority;

        if (swapPricingAttributeLink)
        {
            this.swapPriority(swapPricingAttributeLink);
        }
    }

    private void swapPriority(GUPPricingAttributeLink _newpricingAttributeLink)
    {
        int newPriority;

        ttsbegin;
        newPriority = _newpricingAttributeLink.Priority;
        _newpricingAttributeLink.Priority = this.Priority;
        _newpricingAttributeLink.update();
        this.Priority = newPriority;
        this.update();
        ttscommit;
	}

    /// <summary>
    /// Display a lookup form with all allowed values.
    /// </summary>
    /// <param name = "_control">The target control to be linked with the lookup form.</param>
    public void lookupAllowedValues(FormStringControl _control)
    {
        boolean hasDescription = true;
        Set allowedValues = this.pricingAttribute().getAllowedValuesWithDescription();
        if (allowedValues == null)
        {
            hasDescription = false;
            allowedValues = this.pricingAttribute().getAllowedValues();
        }

        if (this.pricingAttribute().getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST)
        {
            FormRun _formRun;
            Args    args = new Args(formStr(SysLookup));

            args.parm(int2str(this.pricingAttribute().getFixedAllowedValueEnumId()));

            _formRun     = classfactory.formRunClass(args);
            _formRun.init();

            _control.performFormLookup(_formRun);
        }
        else 
        {
            SysTableLookup    lookup;
            QueryBuildDataSource qbds;

            Query q = new Query();
            qbds = q.addDataSource(tableNum(GUPAllowedValuesListTemp));
            qbds.addSortField(fieldNum(GUPAllowedValuesListTemp, Value), SortOrder::Ascending);

            lookup = SysTableLookup::newParameters(tableNum(GUPAllowedValuesListTemp),
                                               _control,
                                               true);

            lookup.addLookupField(fieldnum(GUPAllowedValuesListTemp, Value), true);
        
            if (hasDescription)
            {
                lookup.addLookupField(fieldnum(GUPAllowedValuesListTemp, Description), false);
            }

            lookup.parmQuery(q);
            lookup.parmTmpBuffer(GUPAllowedValuesListTemp::populate(allowedValues, hasDescription));

            lookup.performFormLookup();
        }


    }

    /// <summary>
    /// Convert <c>AttributeDataType</c> to EcoResValue
    /// </summary>
    /// <param name = "_dataType">Type of condition value</param>
    /// <param name = "_value">Value to check</param>
    /// <returns>EcoResValue record</returns>
    internal static EcoResValue getEcoResValue(AttributeDataType _dataType, AttributeValueText _value)
    {
        EcoResValue ecoResValue;

        switch (_dataType)
        {
            case AttributeDataType::Decimal:
                EcoResFloatValue ecoResFloatValue;

                ecoResFloatValue.FloatValue = str2Num(_value);
                ecoResValue                 = ecoResFloatValue;
                break;
            case AttributeDataType::Integer:
                EcoResIntValue ecoResIntValue;

                ecoResIntValue.IntValue = str2Int(_value);
                ecoResValue             = ecoResIntValue;
                break;
            case AttributeDataType::Currency:
                EcoResCurrencyValue ecoResCurrencyValue;

                ecoResCurrencyValue.CurrencyValue   = str2Num(_value);
                ecoResValue                         = ecoResCurrencyValue;
                break;
            case AttributeDataType::DateTime:
                EcoResDateTimeValue ecoResDateTimeValue;
                System.Globalization.CultureInfo culture = System.Globalization.CultureInfo::get_InvariantCulture();
                
                try
                {
                    utcdatetime dateTime = System.DateTime::ParseExact(_value, 'g', culture);
                    ecoResDateTimeValue.DateTimeValue = dateTime;
                }
                catch (Exception::CLRError)
                {
                    throw error(strFmt("@GlobalUnifiedPricing:GUPDateTimeFormatError", culture.DateTimeFormat.ShortDatePattern, culture.DateTimeFormat.ShortTimePattern));
                }

                ecoResValue = ecoResDateTimeValue;
                break;
            case AttributeDataType::Text:
                EcoResTextValue ecoResTextValue;

                ecoResTextValue.TextValue   = _value;
                ecoResValue                 = ecoResTextValue;
                break;
        }

        return ecoResValue;
    }

    /// <summary>
    /// Validate the value
    /// </summary>
    /// <returns>True if the value is correct; Otherwise false</returns>
    internal boolean checkDefaultValue()
    {
        boolean ret = true;

        if (this.DefaultValue)
        {
            if (this.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute))
            {
                EcoResAttributeDefaultValueHelper attributeDefaultValueHelper = new EcoResAttributeDefaultValueHelper(EcoResAttributeType::findByName(this.TypeName));
                AttributeDataType attributeDataType = this.pricingAttribute().getDataType();

                if (attributeDataType != AttributeDataType::TrueFalse
                    && attributeDataType != AttributeDataType::Reference
                    && !attributeDefaultValueHelper.validateDefaultValue(GUPPricingAttributeLink::getEcoResValue(attributeDataType, this.DefaultValue)))
                {
                    ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPAttributeValueRangeError", this.DefaultValue, this.TypeName));
                }
            }
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean ret = super();

        if (ret && GUPPricingAttributeGroup::isPricingAttributeGroupUsed(this.PriceAttributeGroup))
        {
            warning("@GlobalUnifiedPricing:GUPPricingAttributeGroupIsUsed");
            ret = false;
        }

        if (ret)
        {
            ret = ret && this.checkDefaultValue();
        }
    
        return ret;
    }

public boolean validateDelete()
{
    boolean ret = super();

    if (ret && GUPPricingAttributeGroup::isPricingAttributeGroupUsed(this.PriceAttributeGroup))
    {
        warning("@GlobalUnifiedPricing:GUPPricingAttributeGroupIsUsed");
        ret = false;
    }

    return ret;
}

    public void resetAttributeGroupValidation()
    {
        GUPPricingAttributeGroup attGroup;

        select firstonly forupdate attGroup where attGroup.RecId == this.PriceAttributeGroup;

        if (attGroup.IsValid)
        {
            ttsbegin;
            attGroup.IsValid = NoYes::No;
            attGroup.update();
            ttscommit;

            info("@GlobalUnifiedPricing:GUPPricingAttributeGroup_ResetValidation");
        }
    }

    public void update()
    {
        ttsbegin;

        GUPPricingAttributeLink origLink = this.orig();
        boolean priceAttributeChanged = (origLink.AttributeName != this.AttributeName ||
                origLink.TypeName != this.TypeName ||
                origLink.PriceAttributeClassId != this.PriceAttributeClassId);

        super();

        if (priceAttributeChanged)
        {
            this.resetAttributeGroupValidation();
        }
        ttscommit;
    }

    public void insert()
    {
        ttsbegin;

        super();

        this.resetAttributeGroupValidation();

        ttscommit;
    }

    public void delete()
    {
        ttsbegin;

        super();

        this.resetAttributeGroupValidation();

        ttscommit;
    }

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        GUPIPricingAttribute pricingAttr;

        switch (_fieldId)
        {
            case fieldNum(GUPPricingAttributeLink, PriceAttributeClassId):
            case fieldNum(GUPPricingAttributeLink, AttributeProviderClassId):
            case fieldNum(GUPPricingAttributeLink, AttributeName):
            case fieldNum(GUPPricingAttributeLink, TypeName):
                pricingAttr = this.pricingAttribute();
                this.initFromPricingAttribute(pricingAttr);
                break;
        }
    }

    public void initFromPricingAttribute(GUPIPricingAttribute _pricingAttribute, boolean _initClassId = false)
    {
        if (_initClassId)
        {
            RefRecId pricingAttrGroupRecId = this.PriceAttributeGroup;

            this.data(GUPPricingAttributeRepository::toPriceAttributeLink(_pricingAttribute));
            this.PriceAttributeGroup = pricingAttrGroupRecId;
        }

        GUPPricingAttributeFieldsDiscoveryAttribute attributeAsFieldObject =
            GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                _pricingAttribute,
                attributeStr(GUPPricingAttributeFieldsDiscoveryAttribute));

        if (attributeAsFieldObject)
        {
            this.FieldName = (attributeAsFieldObject  as GUPPricingAttributeFieldsDiscoveryAttribute).parmFieldName();
        }

        if (_pricingAttribute is GUPAbstractPricingAttribute)
        {
            this.FieldPath = (_pricingAttribute as GUPAbstractPricingAttribute).getPath();
        }

        this.SourceName = _pricingAttribute.getQueryBuilderDatasourceIdentifier();
        this.AttributeDataType = enum2Str(_pricingAttribute.getDataType());
    }
